CREATE TABLE IF NOT EXISTS shipments (id UUID PRIMARY KEY, reference VARCHAR(100) UNIQUE, origin VARCHAR(100), destination VARCHAR(100), commodity VARCHAR(100), customer VARCHAR(150), status VARCHAR(30), priority VARCHAR(30), created_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS railcars (id UUID PRIMARY KEY, car_number VARCHAR(100) UNIQUE, type VARCHAR(100), capacity INTEGER, location VARCHAR(100), commodity VARCHAR(100), status VARCHAR(30), last_scan_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS trains (id UUID PRIMARY KEY, train_number VARCHAR(100), origin VARCHAR(100), destination VARCHAR(100), departure_at TIMESTAMP WITH TIME ZONE, arrival_at TIMESTAMP WITH TIME ZONE, status VARCHAR(30));
CREATE TABLE IF NOT EXISTS yards (id UUID PRIMARY KEY, code VARCHAR(30) UNIQUE, name VARCHAR(150), city VARCHAR(150), track_capacity INTEGER, occupied_tracks INTEGER);
CREATE TABLE IF NOT EXISTS scan_events (id UUID PRIMARY KEY, car_number VARCHAR(100), yard_code VARCHAR(30), event_type VARCHAR(50), occurred_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS operational_alerts (id UUID PRIMARY KEY, type VARCHAR(50), message VARCHAR(255), entity_reference VARCHAR(100), severity VARCHAR(30), status VARCHAR(30), created_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS route_segments (id UUID PRIMARY KEY, train_number VARCHAR(100), origin_yard VARCHAR(30), destination_yard VARCHAR(30), scheduled_departure TIMESTAMP WITH TIME ZONE, scheduled_arrival TIMESTAMP WITH TIME ZONE, actual_arrival TIMESTAMP WITH TIME ZONE, status VARCHAR(30));